/* Ticktoon scene code — 由 tt build 生成，不要手改；改 storyboard 后重新编译 */
const TT = {};
/* kit:ease */
/**
 * TT.ease —— 缓动曲线集合。
 *
 * 这里只放"能对到一条明确数学式"的曲线，不放可调参数的自由曲线：
 * 每场各自发明 bezier 的结果是整片节奏碎裂，而这类问题在静帧上看不出来。
 * 需要回弹时用 `back(o)`，o 由调用方给具体数字，不用默认值蒙。
 */
(() => {
  TT.ease = {
    linear: (p) => p,
    outCubic: (p) => 1 - Math.pow(1 - p, 3),
    outQuart: (p) => 1 - Math.pow(1 - p, 4),
    outExpo: (p) => (p >= 1 ? 1 : 1 - Math.pow(2, -10 * p)),
    inOutCubic: (p) => (p < 0.5 ? 4 * p * p * p : 1 - Math.pow(-2 * p + 2, 3) / 2),
    /** 工厂：`ease.back(1.7)(p)`，o 越大回弹越狠。 */
    back: (o) => (p) => 1 + (o + 1) * Math.pow(p - 1, 3) + o * Math.pow(p - 1, 2),
  };
})();
/* kit:num */
/**
 * TT.clamp01 / TT.num / TT.env / TT.rng —— 数值与包络。
 *
 * `env` 与 `rng` 放在这里而不是散在各场里，是因为它们必须**全片同一条公式**：
 * 入场包络一旦各写一份，同一片子里的元素就会有不同的淡入手感；
 * rng 一旦各写一份，同一帧两次渲染就可能不一致，确定性直接失效。
 */
(() => {
  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  TT.clamp01 = clamp01;

  TT.num = {
    /** 千分位 + 定点小数；非有限值返回空串，避免画面上出现 NaN。 */
    fmt(v, digits = 0) {
      const n = Number(v);
      if (!Number.isFinite(n)) return '';
      const fixed = Math.abs(n).toFixed(digits);
      const dot = fixed.indexOf('.');
      const intPart = dot < 0 ? fixed : fixed.slice(0, dot);
      const frac = dot < 0 ? '' : fixed.slice(dot);
      return (n < 0 ? '-' : '') + intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ',') + frac;
    },
  };

  TT.env = {
    /** 入场淡入 + 出场淡出的最小值。`dur` 是本场景的可见时长。 */
    fade(t, dur, inDur, outDur) {
      const a = inDur > 0 ? clamp01(t / inDur) : 1;
      const b = outDur > 0 ? clamp01((dur - t) / outDur) : 1;
      return a < b ? a : b;
    },
    /** 0…1 的线性入场进度；曲线由调用方自己从 TT.ease 里选。 */
    reveal(t, inDur) {
      return inDur > 0 ? clamp01(t / inDur) : 1;
    },
  };

  /** mulberry32：定长状态、无外部依赖，每帧从同一 seed 重开即是同一数列。 */
  TT.rng = (seed) => {
    let a = (seed >>> 0) || 1;
    return () => {
      a = (a + 0x6d2b79f5) | 0;
      let t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  };
})();
/* kit:text */
/**
 * TT.text —— 排版、量测、真实墨迹框。
 *
 * 断行规则是中文优先：CJK 逐字可断，西文按词，空格是唯一允许被丢弃的断点。
 * 这不是通用排版引擎，是"播报字幕级"的排版：不处理标点悬挂、不做两端对齐，
 * 因为这两件事在 1080p 短片上肉眼不可辨，却会让量测结果与实际绘制对不上。
 */
(() => {
  const CJK = /[\u2e80-\u303f\u3040-\u9fff\uac00-\ud7af\uf900-\ufaff\ufe30-\ufe4f\uff00-\uffef]/;

  /** 把一段文字切成"不可再分的最小单元"：CJK 单字、西文单词、单个空格。 */
  function tokenize(str) {
    const out = [];
    let word = '';
    for (const ch of str) {
      if (CJK.test(ch)) {
        if (word) out.push(word), (word = '');
        out.push(ch);
      } else if (ch === ' ' || ch === '\t') {
        if (word) out.push(word), (word = '');
        out.push(' ');
      } else {
        word += ch;
      }
    }
    if (word) out.push(word);
    return out;
  }

  function layout(ctx, str, maxWidth) {
    const lines = [];
    for (const paragraph of String(str == null ? '' : str).split('\n')) {
      if (paragraph === '') {
        lines.push('');
        continue;
      }
      let line = '';
      for (const token of tokenize(paragraph)) {
        const next = line + token;
        if (line && ctx.measureText(next).width > maxWidth) {
          lines.push(line.replace(/\s+$/, ''));
          line = token === ' ' ? '' : token;
        } else {
          line = next;
        }
      }
      if (line) lines.push(line.replace(/\s+$/, ''));
    }
    return lines;
  }

  // ---- 文字回执：独立于 TT.pen 的墨迹框，只累计本帧真正 fillText 出去的文字 ----
  // 逐条记账（textItems）与并集记账（textBBox）同时保留：并集供安全框断言，
  // 逐条供"同场文字互相压住"的碰撞检测。code 场由 emit 每帧 resetBBox；
  // raw ctx.fillText 由 emit 注入的包装器自动记账，TT.text(...) 走同一套量测。
  let textBBox = null;
  let textItems = [];
  const LABEL_LIMIT = 40;
  const finite = (value) => typeof value === 'number' && Number.isFinite(value);

  function fontSize(ctx) {
    const match = /([\d.]+)px/.exec(String(ctx.font || ''));
    return match ? Number(match[1]) : 0;
  }

  /**
   * 量测一段文字在当前 ctx 状态下的真实墨迹框（画布逻辑像素），不累计。
   * actualBoundingBox* 已按 textAlign / textBaseline 给出相对对齐点的距离；
   * 引擎不提供时按字号与对齐方式保守回退。
   */
  function measureBox(ctx, str, x, y) {
    const value = String(str == null ? '' : str);
    if (!value.trim()) return null;
    let metrics = null;
    try {
      metrics = ctx.measureText(value);
    } catch {
      return null;
    }
    if (!metrics) return null;
    const width = finite(metrics.width) ? metrics.width : 0;
    const left = finite(metrics.actualBoundingBoxLeft) ? metrics.actualBoundingBoxLeft : null;
    const right = finite(metrics.actualBoundingBoxRight) ? metrics.actualBoundingBoxRight : null;
    const asc = finite(metrics.actualBoundingBoxAscent) ? metrics.actualBoundingBoxAscent : null;
    const desc = finite(metrics.actualBoundingBoxDescent) ? metrics.actualBoundingBoxDescent : null;
    const size = fontSize(ctx);
    let x0;
    let x1;
    if (left !== null && right !== null) {
      x0 = x - left;
      x1 = x + right;
    } else {
      const align = ctx.textAlign || 'left';
      const w = width;
      x0 = align === 'center' ? x - w / 2 : align === 'right' || align === 'end' ? x - w : x;
      x1 = x0 + w;
    }
    const ascPx = asc !== null ? asc : size * 0.78;
    const descPx = desc !== null ? desc : size * 0.22;
    const y0 = y - ascPx;
    const y1 = y + descPx;
    if (!(x1 > x0 && y1 > y0)) return null;

    let matrix = null;
    try {
      matrix = typeof ctx.getTransform === 'function' ? ctx.getTransform() : null;
    } catch {
      matrix = null;
    }
    const corners = [[x0, y0], [x1, y0], [x1, y1], [x0, y1]];
    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;
    for (const [px, py] of corners) {
      const tx = matrix ? matrix.a * px + matrix.c * py + matrix.e : px;
      const ty = matrix ? matrix.b * px + matrix.d * py + matrix.f : py;
      if (tx < minX) minX = tx;
      if (ty < minY) minY = ty;
      if (tx > maxX) maxX = tx;
      if (ty > maxY) maxY = ty;
    }
    if (!(maxX > minX && maxY > minY)) return null;
    return { x: minX, y: minY, w: maxX - minX, h: maxY - minY };
  }

  function accumulate(box) {
    if (!box) return;
    if (!textBBox) {
      textBBox = { x0: box.x, y0: box.y, x1: box.x + box.w, y1: box.y + box.h };
    } else {
      if (box.x < textBBox.x0) textBBox.x0 = box.x;
      if (box.y < textBBox.y0) textBBox.y0 = box.y;
      if (box.x + box.w > textBBox.x1) textBBox.x1 = box.x + box.w;
      if (box.y + box.h > textBBox.y1) textBBox.y1 = box.y + box.h;
    }
  }

  /**
   * 记一条文字：并集 + 逐条。label 取 fillText 的第一个参数（原始字符串）截断 40 字符，
   * 只用于报告/碰撞文案；bbox 是量测后的画布逻辑像素框。
   */
  function remember(ctx, str, box) {
    if (!box) return box;
    accumulate(box);
    textItems.push({
      text: String(str == null ? '' : str).slice(0, LABEL_LIMIT),
      bbox: { x: box.x, y: box.y, w: box.w, h: box.h },
      size: fontSize(ctx),
    });
    return box;
  }

  function record(ctx, str, x, y) {
    return remember(ctx, str, measureBox(ctx, str, x, y));
  }

  /**
   * TT.text(ctx, text, x, y, size, opts) —— 写一行文字并记账。
   * opts: font(css 字符串或 TT.font 结果) / fontKey(manifest 字体键) / color / align /
   * baseline / alpha / maxWidth。默认字体 sans-400；调用方仍可用 ctx 状态画更复杂的排版。
   */
  function draw(ctx, str, x, y, size, opts = {}) {
    if (!ctx) return null;
    const o = opts || {};
    const font = o.font == null
      ? (typeof TT.font === 'function' && typeof FONTS !== 'undefined'
        ? TT.font(FONTS, finite(size) ? size : 56, o.fontKey || 'sans-400')
        : null)
      : (typeof o.font === 'string' ? { css: o.font } : o.font);
    ctx.save();
    if (font && font.css) ctx.font = font.css;
    if (o.color != null) ctx.fillStyle = o.color;
    if (finite(o.alpha)) ctx.globalAlpha *= o.alpha;
    ctx.textAlign = o.align || 'left';
    ctx.textBaseline = o.baseline || 'alphabetic';
    const prev = ctx.__ttTextInternal;
    ctx.__ttTextInternal = true;
    let box = null;
    try {
      if (o.maxWidth != null) ctx.fillText(str, x, y, o.maxWidth);
      else ctx.fillText(str, x, y);
      box = measureBox(ctx, str, x, y);
      if (box) remember(ctx, str, box);
    } finally {
      ctx.__ttTextInternal = prev;
      ctx.restore();
    }
    return box;
  }

  Object.assign(draw, {
    bbox() {
      if (!textBBox) return null;
      return { x: textBBox.x0, y: textBBox.y0, w: textBBox.x1 - textBBox.x0, h: textBBox.y1 - textBBox.y0 };
    },

    /** 本帧逐条文字 `{ text, bbox, size }`；顺序就是本帧 fillText 的绘制顺序。 */
    items() {
      return textItems.map((item) => ({
        text: item.text,
        bbox: { x: item.bbox.x, y: item.bbox.y, w: item.bbox.w, h: item.bbox.h },
        size: item.size,
      }));
    },

    resetBBox() { textBBox = null; textItems = []; },

    measureBox,
    record,

    measure(ctx, str) {
      return ctx.measureText(str).width;
    },

    wrap(ctx, str, maxWidth) {
      return layout(ctx, str, maxWidth);
    },

    /**
     * 从显式的最大像素字号往下试，直到整段能塞进 rect。
     * 返回 `{ font, lines }`；到 minPx 仍塞不下时返回最小字号的结果，
     * 由调用方（或 check）决定是截断还是改文案。
     */
    fit(ctx, str, rect, fonts, fontKey, maxPx, minPx) {
      const from = maxPx;
      const floor = minPx || 32;
      let best = null;
      for (let px = from; px >= floor; px -= 2) {
        const font = TT.font(fonts, px, fontKey);
        ctx.font = font.css;
        const lines = layout(ctx, str, rect.w);
        best = { font, lines };
        if (lines.length * font.lineHeight <= rect.h) return best;
      }
      return best;
    },

    /**
     * 真实墨迹包围盒，供 receipts 用。`input` 可以是字符串（内部再断行）
     * 或已排好的行数组——调用方已经算过行时传数组，省一次量测且保证与绘制一致。
     */
    inkBox(ctx, input, rect, font, align) {
      const lines = Array.isArray(input) ? input : layout(ctx, input, rect.w);
      const prevFont = ctx.font;
      ctx.font = font.css;
      const linesH = lines.length * font.lineHeight;
      const top = align === 'middle' ? rect.y + (rect.h - linesH) / 2 : rect.y;

      let left = Infinity;
      let right = -Infinity;
      let inkTop = Infinity;
      let inkBottom = -Infinity;

      lines.forEach((line, i) => {
        if (!line) return;
        const m = ctx.measureText(line);
        const baseline = top + i * font.lineHeight + font.ascent;
        const asc = typeof m.actualBoundingBoxAscent === 'number' ? m.actualBoundingBoxAscent : font.ascent;
        const desc = typeof m.actualBoundingBoxDescent === 'number' ? m.actualBoundingBoxDescent : font.descent;
        if (m.width > 0) {
          left = Math.min(left, rect.x);
          right = Math.max(right, rect.x + m.width);
          inkTop = Math.min(inkTop, baseline - asc);
          inkBottom = Math.max(inkBottom, baseline + desc);
        }
      });

      ctx.font = prevFont;
      if (!Number.isFinite(left)) return { x: rect.x, y: rect.y, w: 0, h: 0 };
      return { x: left, y: inkTop, w: right - left, h: inkBottom - inkTop };
    },
  });

  // 可调用（TT.text(ctx, …)），同时保留 measure / wrap / fit / inkBox / bbox 等成员。
  TT.text = draw;
})();
/* kit:fonts */
/**
 * TT.font —— 场景字体资源的唯一查询。
 *
 * fonts 是该场声明的字体键映射（manifest 键 → 同名键）；它对应本场
 * `resources` 里的 font 条目，是资源加载与授权契约，不是配色板。
 * 颜色由 kit 自带默认值，或由 scene.code 直接写 hex。
 * 字号、行高、字重、版位一律由调用方显式给，这里不做隐式查表。
 *
 * font 返回的 `css` 里那个族名字符串**必须**等于 `resources[].name`。
 * 引擎注册字体走 `new FontFace(name, bytes)`，族名就是资源名；
 * 写成 "Source Han Sans" 而资源叫 "sans-400" 时不会报错，只会静默回落到系统字体——
 * 画面照常出，字全错了。字体键一律从 manifest 取，不手写 family。
 */
(() => {
  TT.font = (fonts, size, fontKey, familyOverride) => {
    if (typeof size !== 'number' || !Number.isFinite(size) || size <= 0) {
      throw new Error('Font size must be a positive number: ' + size);
    }
    const family = familyOverride || fonts?.[fontKey || 'sans-900'];
    if (!family) throw new Error('Unknown font key: ' + fontKey);
    return {
      css: size + 'px "' + family + '"',
      size,
      family,
      lineHeight: size * 1.24,
      ascent: size * 0.78,
      descent: size * 0.22,
    };
  };
})();
/* kit:board */
/**
 * TT.board —— 舞台底。
 *
 * 纸面纤维、绿板渐变、粉笔槽与板擦是整类片子的公共底；code 场与 params 模板都调用
 * 同一套词法，才能看起来是一部片子。这里只抽"底"，不抽内容：
 * 笔迹仍然只走 TT.pen，文本仍然由调用方画。
 *
 * 舞台是词法：纸有几种是有限的，讲什么故事是无限的。所以这一层写死，
 * 由 LLM 从 TT.board.list() 里挑，而不是让每片各画一遍底色。
 *
 * W/H 优先取 api.W/api.H（逻辑尺寸）；没有 api 时退回 ctx.canvas 的像素尺寸。
 * 所有内部扰动都是序号与固定常量的函数，不依赖墙钟或随机数。
 */
(() => {
  const TAU = Math.PI * 2;

  /**
   * 确定性伪随机：只吃整数序号与 seed，绝不读墙钟。
   * 同一个 (n, seed) 永远得同一个 [0,1) 值，`tt det` 才能两次跑出同一张图。
   */
  const rnd = (n, seed) => {
    let x = (Math.imul(n | 0, 374761393) + Math.imul(seed | 0, 668265263)) | 0;
    x = (x ^ (x >>> 13)) | 0;
    x = Math.imul(x, 1274126177) | 0;
    x = (x ^ (x >>> 16)) >>> 0;
    return x / 4294967296;
  };

  const seedOf = (opts) => {
    const s = Number(opts?.seed);
    return Number.isFinite(s) ? Math.round(s) : 0;
  };

  /**
   * 纹理尺度基准：一律按短边定量。
   * 按长边铺固定条数会在 9:16 与 1:1 之间把纹理拉成两套密度，看起来像换了张纸。
   */
  const unitOf = (W, H) => Math.min(W, H) / 1000;

  /** 整体色偏：tone ∈ [-1,1]，正暖负冷。零值严格不落笔，保证老路径零像素变化。 */
  function toneOverlay(ctx, W, H, opts) {
    const tone = Number(opts?.tone);
    if (!Number.isFinite(tone) || tone === 0) return;
    const t = Math.max(-1, Math.min(1, tone));
    ctx.save();
    ctx.fillStyle = t > 0
      ? `rgba(255,196,120,${(0.11 * t).toFixed(4)})`
      : `rgba(120,170,255,${(0.11 * -t).toFixed(4)})`;
    ctx.fillRect(0, 0, W, H);
    ctx.restore();
  }

  const roundRect = (ctx, x, y, w, h, r) => {
    const radius = Math.max(0, Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2));
    ctx.beginPath();
    if (typeof ctx.roundRect === 'function') ctx.roundRect(x, y, w, h, radius);
    else {
      ctx.moveTo(x + radius, y);
      ctx.arcTo(x + w, y, x + w, y + h, radius);
      ctx.arcTo(x + w, y + h, x, y + h, radius);
      ctx.arcTo(x, y + h, x, y, radius);
      ctx.arcTo(x, y, x + w, y, radius);
      ctx.closePath();
    }
  };

  const sizeOf = (ctx, api) => ({
    W: Number.isFinite(api?.W) ? api.W : ctx.canvas.width,
    H: Number.isFinite(api?.H) ? api.H : ctx.canvas.height,
  });

  /** 很淡的纸/板面纤维：位置是固定公式，避免每帧闪烁。满幅背景不进镜头变换。 */
  function fibers(ctx, W, H, blackboard) {
    ctx.save();
    ctx.strokeStyle = blackboard ? 'rgba(235,240,220,0.035)' : 'rgba(112,98,73,0.045)';
    ctx.lineWidth = 1;
    for (let i = 0; i < 115; i += 1) {
      const x = (i * 167.31 + 37) % W;
      const y = (i * i * 19.17 + i * 43.7) % H;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + 18 + (i % 5) * 7, y + Math.sin(i) * 3);
      ctx.stroke();
    }
    ctx.fillStyle = blackboard ? 'rgba(235,240,220,0.04)' : 'rgba(98,83,59,0.055)';
    for (let i = 0; i < 180; i += 1) {
      ctx.fillRect((i * 311.7) % W, (i * i * 7.93 + 71) % H, 1.4, 1.4);
    }
    ctx.restore();
  }

  /** 白纸底：与原 scene.whiteboard 的 paper 分支逐像素一致。 */
  function paper(ctx, api, opts = {}) {
    const { W, H } = sizeOf(ctx, api);
    ctx.fillStyle = opts.paper || '#f8f5ec';
    ctx.fillRect(0, 0, W, H);
    fibers(ctx, W, H, false);
  }

  /** 绿板底 + 粉笔槽/板擦：与原 scene.whiteboard 的 blackboard 分支逐像素一致。 */
  function blackboard(ctx, api, opts = {}) {
    const { W, H } = sizeOf(ctx, api);

    // 深绿板面：中心略亮、四周压暗，保留粉笔擦过的雾面痕迹。
    const board = ctx.createLinearGradient(0, 0, W * 0.35, H);
    board.addColorStop(0, '#38695b');
    board.addColorStop(0.48, '#2F5D50');
    board.addColorStop(1, '#274d43');
    ctx.fillStyle = board;
    ctx.fillRect(0, 0, W, H);
    ctx.save();
    ctx.fillStyle = 'rgba(230,238,220,0.028)';
    for (let i = 0; i < 9; i += 1) {
      ctx.beginPath();
      ctx.ellipse(W * (0.12 + i * 0.1), H * (0.18 + (i % 4) * 0.19), 120 + (i % 3) * 45, 48 + (i % 2) * 22, i * 0.4, 0, TAU);
      ctx.fill();
    }
    // 内框木边，固定屏幕坐标，不随镜头缩放。
    ctx.strokeStyle = 'rgba(18,32,27,0.55)';
    ctx.lineWidth = 14;
    ctx.strokeRect(7, 7, W - 14, H - 14);
    ctx.strokeStyle = 'rgba(220,225,205,0.10)';
    ctx.lineWidth = 2;
    ctx.strokeRect(15, 15, W - 30, H - 30);
    ctx.restore();

    fibers(ctx, W, H, true);

