  /**
   * 老两种一格都没动，只在外层补 tone。
   * tone 为空时包装层不落任何笔，静帧与 v7 逐像素一致。
   */
  const withTone = (fn) => (ctx, api, opts = {}) => {
    fn(ctx, api, opts);
    const { W, H } = sizeOf(ctx, api);
    toneOverlay(ctx, W, H, opts);
  };

